 const notifications=[...orders.slice(0,4).map(o=>({title:'New order '+o.order_number,detail:o.customer_name+' · '+money(o.total),time:o.created_at,kind:'order'})),...lowStock.slice(0,3).map(p=>({title:'Low stock: '+p.name,detail:String(p.stockQuantity)+' remaining',time:'',kind:'stock'}))].slice(0,6);
 function exportOrders(){const rows=[['Order number','Date','Customer','Phone','Total KES','Status'],...filteredOrders.map(o=>[o.order_number,o.created_at,o.customer_name,o.customer_phone,o.total,o.status])];const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='dasnet-orders-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(url);}
 async function copyStore(){if(!shop)return;try{await navigator.clipboard.writeText(window.location.origin+'/'+shop.slug);setNotice('Store link copied.')}catch{setNotice(window.location.origin+'/'+shop.slug)}}
 const nav=[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'orders',label:'Orders & Sales',icon:ShoppingBag},{id:'products',label:'Products',icon:Package},{id:'transactions',label:'Transactions',icon:WalletCards},{id:'payouts',label:'Payout Settings',icon:Wallet},{id:'api',label:'API Credentials',icon:ShieldCheck},{id:'tickets',label:'Support Tickets',icon:HelpCircle},{id:'notifications',label:'Notifications',icon:Bell},{id:'account',label:'My Account',icon:Store},{id:'settings',label:'Shop Settings',icon:Settings}];
