      <section className="seller-panel seller-notification-panel"><div className="seller-panel-head"><div><h2>Recent notifications</h2><p>Orders and stock reminders</p></div><button className="seller-text-action" onClick={()=>setTab('notifications')}>View all <ArrowRight size={14}/></button></div>{notifications.map((n,i)=><div className="seller-notice-row" key={n.title+i}><span className={n.kind==='stock'?'stock':'order'}>{n.kind==='stock'?<CircleAlert size={15}/>:<ShoppingBag size={15}/>}</span><div><strong>{n.title}</strong><small>{n.detail}</small></div><time>{n.time?new Date(n.time).toLocaleDateString('en-KE'):'Now'}</time></div>)}{notifications.length===0&&<p className="seller-empty">No new notifications.</p>}</section>
