     {editing&&<form className="seller-editor" onSubmit={saveProduct}><div className="seller-editor-grid"><label>Product name<input required maxLength={120} value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})}/></label><label>Product type<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option value="physical">Shop product</option><option value="data_bundle">Data bundle</option><option value="digital">Digital product</option></select></label><label>Price (KES)<input required type="number" min="0" step="0.01" value={editing.price} onChange={e=>setEditing({...editing,price:e.target.value})}/></label><label>Stock quantity<input type="number" min="0" step="1" placeholder="Leave blank if not tracked" value={editing.stock??''} onChange={e=>setEditing({...editing,stock:e.target.value})}/></label><label className="wide">Description<textarea maxLength={2000} rows={3} value={editing.description} onChange={e=>setEditing({...editing,description:e.target.value})}/></label><label>SKU<input maxLength={80} value={editing.sku||''} onChange={e=>setEditing({...editing,sku:e.target.value})}/></label><label className="wide">Product images<input type="file" accept="image/png,image/jpeg,image/webp" multiple onChange={async e=>{const files=Array.from(e.target.files||[]);if(files.length>5){setError('Maximum five images.');return;}try{const images=await Promise.all(files.map(file=>new Promise<string>((resolve,reject)=>{if(file.size>900000){reject(Error('Each image must be under 900 KB.'));return;}const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error('Image read failed'));reader.readAsDataURL(file)})));setEditing((v:any)=>({...v,images}));}catch(err:any){setError(err.message)}}}/><small>PNG, JPEG or WebP · up to 5 images</small><div className="seller-image-preview">{(editing.images||[]).map((src:string,i:number)=><img key={i} src={src} alt={'Product '+(i+1)}/>)}</div></label></div><div className="seller-editor-actions"><button className="seller-primary-btn" disabled={saving}>{saving?'Saving…':'Save product'}</button><button type="button" className="seller-secondary-btn" onClick={()=>setEditing(null)}>Cancel</button></div></form>}
